#include <stdlib.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int sz = 2 * n - 1;
    for (int r = 0; r < sz; r++) {
        for (int c = 0; c < sz; c++) {
            int dr = abs(r - (n - 1)), dc = abs(c - (n - 1));
            int d = dr > dc ? dr : dc;
            printf("%d", d + 1);
        }
        printf("\n");
    }
    return 0;
}

