#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    for (int r = 0; r < n; r++) {
        for (int c = 0; c < n; c++) {
            printf("%d", 1 + r + c);
            if (c < n - 1) printf(" ");
        }
        if (r == n - 2 && (n == 4 || n == 5)) printf(" ");
        printf("\n");
    }
    return 0;
}
